SELECT fn_cp_import_case('vuln-personne-etrangere-isolee-sans-recours', '{"slug": "vuln-personne-etrangere-isolee-sans-recours", "title": "Elle est arrivée il y a deux mois et ne connaît personne", "theme_slug": "personnes-vulnerables", "difficulty": "moyen", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 25, "situation_text": "Il est 18 heures. Au commissariat, une personne étrangère arrivée en France il y a deux mois se présente à vous dans un isolement social et culturel total, ne connaissant personne sur ce territoire et manifestant une méfiance perceptible envers les institutions qu''elle rencontre. Cette configuration, où cet isolement complet s''accompagne d''une difficulté à faire confiance aux services qu''elle sollicite, nécessite d''orienter cette personne vers des relais adaptés à sa situation tout en instaurant progressivement la confiance nécessaire à cette prise en charge.\n\nCette situation, caractéristique des difficultés que peut rencontrer une personne récemment arrivée sur le territoire et dépourvue de tout réseau social ou familial, impose une approche patiente qui construise cette confiance indispensable avant toute orientation efficace vers ces relais appropriés.\n\nCette configuration nécessite d''orienter vers des relais adaptés et d''instaurer la confiance, cette double exigence restant essentielle pour offrir à cette personne une prise en charge effective malgré cet isolement et cette méfiance institutionnelle initiale.", "questions": [{"position": 1, "max_points": 5, "label": "Comment instaurez-vous progressivement la confiance nécessaire avec cette personne étrangère isolée ?", "hint": "Cette confiance doit se construire progressivement, cette patience restant essentielle pour surmonter la méfiance institutionnelle manifestée par cette personne récemment arrivée sur le territoire.", "perfect": "Je reste patiente et bienveillante dans mon accueil de cette personne, cette approche restant essentielle pour surmonter sa méfiance envers les institutions.\n\nJe reste factuelle et transparente sur mon rôle et les suites possibles de cette rencontre, cette clarté restant utile pour rassurer cette personne isolée.\n\nJe reste attentive à recourir à un interprète si la barrière de la langue complique cet échange, cette facilitation restant nécessaire pour cette communication.\n\nJe reste attentive à ne pas presser cette personne dans ses explications, cette patience restant appropriée compte tenu de cet isolement et de cette méfiance initiale.", "points": [{"position": 1, "label": "Rester patiente et bienveillante pour surmonter cette méfiance institutionnelle", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : confiance construite progressivement.", "groups": [{"position": 1, "keywords": ["confiance construite", "méfiance surmontée", "bienveillance appliquée"]}]}, {"position": 2, "label": "Rester factuelle et transparente sur son rôle et les suites possibles", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Clarté rassurant cette personne isolée.", "groups": [{"position": 1, "keywords": ["rôle expliqué", "transparence assurée", "personne rassurée"]}]}, {"position": 3, "label": "Recourir à un interprète si la barrière de la langue le complique", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Facilitation nécessaire pour cette communication.", "groups": [{"position": 1, "keywords": ["interprète sollicité", "langue facilitée", "communication assurée"]}]}, {"position": 4, "label": "Ne pas presser cette personne dans ses explications", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Patience appropriée face à l''isolement.", "groups": [{"position": 1, "keywords": ["patience appliquée", "explications respectées", "isolement pris en compte"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment orientez-vous cette personne vers des relais adaptés à sa situation d''isolement ?", "hint": "Cette orientation doit rester concrète, cette exigence restant essentielle pour proposer à cette personne des relais effectivement adaptés à cette situation d''isolement social et culturel qu''elle traverse.", "perfect": "J''identifie les relais associatifs et institutionnels adaptés à la situation de cette personne récemment arrivée sur le territoire.\n\nJe reste factuelle sur les modalités concrètes de contact avec ces relais, cette précision restant utile pour faciliter cette orientation effective.\n\nJe reste attentive à m''assurer que cette personne comprend bien l''utilité de ces relais proposés, cette compréhension restant essentielle pour leur efficacité.\n\nJe reste attentive à vérifier, si possible, la mise en relation effective avec ces relais avant de considérer cette orientation comme aboutie.", "points": [{"position": 1, "label": "Identifier les relais associatifs et institutionnels adaptés à sa situation", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : relais adaptés identifiés.", "groups": [{"position": 1, "keywords": ["relais identifiés", "situation adaptée", "institutions concernées"]}]}, {"position": 2, "label": "Préciser factuellement les modalités concrètes de contact avec ces relais", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Orientation effective facilitée.", "groups": [{"position": 1, "keywords": ["modalités précisées", "contact facilité", "orientation effective"]}]}, {"position": 3, "label": "S''assurer que cette personne comprend l''utilité de ces relais proposés", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Compréhension essentielle pour l''efficacité.", "groups": [{"position": 1, "keywords": ["utilité comprise", "relais compris", "efficacité assurée"]}]}, {"position": 4, "label": "Vérifier la mise en relation effective avant de considérer l''orientation aboutie", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Mise en relation confirmée.", "groups": [{"position": 1, "keywords": ["mise en relation", "orientation aboutie", "vérification effectuée"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment traitez-vous la demande initiale de cette personne qui l''a conduite à se présenter au commissariat ?", "hint": "Ce traitement doit rester approprié, cette exigence restant essentielle pour répondre à la demande initiale de cette personne indépendamment de cette orientation complémentaire vers des relais adaptés.", "perfect": "Je traite en premier lieu la demande initiale qui a conduit cette personne à se présenter au commissariat, cette priorité restant appropriée.\n\nJe reste factuelle sur les suites données à cette demande, cette clarté restant utile pour cette personne encore peu familière de ce fonctionnement institutionnel.\n\nJe reste attentive à ne pas la renvoyer sans réponse concrète à sa demande initiale, cette exigence restant essentielle malgré cette orientation complémentaire.\n\nJe reste attentive à documenter cette rencontre pour faciliter un suivi si cette personne devait se représenter ultérieurement.", "points": [{"position": 1, "label": "Traiter en premier lieu la demande initiale ayant motivé cette venue", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : priorité à la demande initiale.", "groups": [{"position": 1, "keywords": ["demande traitée", "priorité assurée", "venue motivée"]}]}, {"position": 2, "label": "Rester factuelle sur les suites données à cette demande", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Clarté pour cette personne peu familière du fonctionnement.", "groups": [{"position": 1, "keywords": ["suites précisées", "clarté assurée", "fonctionnement expliqué"]}]}, {"position": 3, "label": "Ne pas la renvoyer sans réponse concrète à sa demande initiale", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Exigence essentielle malgré l''orientation complémentaire.", "groups": [{"position": 1, "keywords": ["réponse concrète", "renvoi évité", "demande satisfaite"]}]}, {"position": 4, "label": "Documenter cette rencontre pour faciliter un suivi ultérieur", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Suivi facilité en cas de retour.", "groups": [{"position": 1, "keywords": ["rencontre documentée", "suivi facilité", "retour anticipé"]}]}]}]}'::jsonb);
SELECT fn_cp_import_case('vuln-suspicion-traite-des-etres-humains', '{"slug": "vuln-suspicion-traite-des-etres-humains", "title": "Elles répondent toutes la même chose, mot pour mot", "theme_slug": "personnes-vulnerables", "difficulty": "expert", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 35, "situation_text": "Il est 16 heures. Dans un salon de manucure, vous constatez que plusieurs employées répondent toutes la même chose, mot pour mot, à vos questions de contrôle, cette uniformité suspecte constituant un indice parmi d''autres d''une exploitation possible derrière cette activité en apparence licite. Cette configuration, où ces victimes potentielles se déclarent pourtant elles-mêmes consentantes à leur situation, nécessite de repérer les indices caractéristiques de cette exploitation et d''isoler ces personnes pour les entendre individuellement, loin de toute pression susceptible de fausser leurs déclarations.\n\nCette situation, caractéristique des réseaux de traite des êtres humains qui peuvent se dissimuler derrière une activité commerciale en apparence conforme, impose un repérage attentif de ces indices caractéristiques ainsi qu''une méthode d''audition qui neutralise l''influence exercée sur ces victimes potentielles.\n\nCette configuration nécessite de repérer les indices et d''isoler les personnes pour les entendre, cette double exigence restant essentielle pour révéler la réalité de cette exploitation malgré ce consentement apparent exprimé par ces victimes potentielles.", "questions": [{"position": 1, "max_points": 5, "label": "Comment repérez-vous les indices caractéristiques de cette exploitation derrière cette activité en apparence licite ?", "hint": "Ce repérage doit rester méthodique, cette rigueur restant essentielle pour identifier les indices caractéristiques d''une exploitation qui se dissimule derrière cette activité commerciale en apparence conforme.", "perfect": "Je repère cette uniformité suspecte des réponses données par ces employées, cet indice restant caractéristique d''un discours potentiellement imposé.\n\nJe reste factuelle en observant d''autres indices matériels, comme les conditions de logement, de rémunération ou de détention de documents d''identité de ces personnes.\n\nJe reste attentive aux comportements non verbaux de ces personnes lors de ce contrôle, ces signaux restant utiles pour compléter cette évaluation.\n\nJe reste attentive à documenter précisément chacun de ces indices constatés, cette traçabilité restant essentielle pour la suite de cette procédure.", "points": [{"position": 1, "label": "Repérer cette uniformité suspecte comme indice d''un discours potentiellement imposé", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : indice caractéristique identifié.", "groups": [{"position": 1, "keywords": ["uniformité repérée", "discours imposé", "indice identifié"]}]}, {"position": 2, "label": "Observer d''autres indices matériels sur logement, rémunération, documents", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Indices matériels complémentaires observés.", "groups": [{"position": 1, "keywords": ["indices matériels", "documents vérifiés", "conditions observées"]}]}, {"position": 3, "label": "Rester attentive aux comportements non verbaux de ces personnes", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Signaux complétant cette évaluation.", "groups": [{"position": 1, "keywords": ["comportements observés", "signaux complémentaires", "évaluation complétée"]}]}, {"position": 4, "label": "Documenter précisément chacun de ces indices constatés", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Traçabilité essentielle pour la procédure.", "groups": [{"position": 1, "keywords": ["indices documentés", "traçabilité assurée", "procédure suivie"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment isolez-vous ces personnes pour les entendre individuellement loin de toute pression ?", "hint": "Cet isolement doit rester méthodique, cette exigence restant essentielle pour neutraliser l''influence potentiellement exercée sur ces victimes lors de leur audition individuelle.", "perfect": "J''organise l''audition individuelle de chacune de ces personnes séparément, cet isolement restant essentiel pour neutraliser toute influence exercée entre elles.\n\nJe reste factuelle dans mes questions posées à chacune de ces personnes, évitant toute question suggestive qui pourrait orienter leurs réponses.\n\nJe reste attentive à écarter physiquement toute personne susceptible d''exercer une pression sur ces employées durant cette audition individuelle.\n\nJe reste attentive à recourir à un interprète indépendant si nécessaire, cette indépendance restant essentielle pour ne pas fausser cette audition.", "points": [{"position": 1, "label": "Organiser l''audition individuelle de chacune de ces personnes séparément", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : influence neutralisée entre les personnes.", "groups": [{"position": 1, "keywords": ["audition individuelle", "personnes séparées", "influence neutralisée"]}]}, {"position": 2, "label": "Poser des questions factuelles évitant toute suggestion", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Questions non suggestives préservant la fiabilité.", "groups": [{"position": 1, "keywords": ["questions factuelles", "suggestion évitée", "fiabilité préservée"]}]}, {"position": 3, "label": "Écarter physiquement toute personne susceptible d''exercer une pression", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Pression écartée durant l''audition.", "groups": [{"position": 1, "keywords": ["pression écartée", "personnes éloignées", "audition sécurisée"]}]}, {"position": 4, "label": "Recourir à un interprète indépendant si nécessaire", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Indépendance essentielle pour cette audition.", "groups": [{"position": 1, "keywords": ["interprète indépendant", "audition fiabilisée", "traduction sécurisée"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment traitez-vous ce consentement apparent exprimé par ces victimes potentielles ?", "hint": "Ce consentement apparent doit être analysé avec prudence, cette exigence restant essentielle pour ne pas se satisfaire d''une déclaration qui pourrait résulter précisément de l''emprise exercée sur ces victimes.", "perfect": "Je reste attentive à ne pas me satisfaire de ce consentement apparent, cette déclaration pouvant précisément résulter de l''emprise exercée sur ces victimes potentielles.\n\nJe reste factuelle en confrontant ce discours de consentement aux éléments matériels objectivement constatés sur les lieux de ce contrôle.\n\nJe reste attentive à transmettre ces éléments aux services spécialisés compétents en matière de traite des êtres humains, cette transmission restant essentielle.\n\nJe reste attentive à ne pas exposer ces personnes à des représailles en révélant prématurément mes soupçons devant d''éventuels complices présents.", "points": [{"position": 1, "label": "Ne pas se satisfaire de ce consentement apparent pouvant résulter d''une emprise", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : consentement apparent questionné.", "groups": [{"position": 1, "keywords": ["consentement questionné", "emprise suspectée", "vigilance maintenue"]}]}, {"position": 2, "label": "Confronter ce discours aux éléments matériels objectivement constatés", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Confrontation objective du discours.", "groups": [{"position": 1, "keywords": ["discours confronté", "éléments matériels", "objectivité assurée"]}]}, {"position": 3, "label": "Transmettre ces éléments aux services spécialisés en traite des êtres humains", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Transmission essentielle aux services compétents.", "groups": [{"position": 1, "keywords": ["services spécialisés", "éléments transmis", "traite signalée"]}]}, {"position": 4, "label": "Ne pas exposer ces personnes à des représailles en révélant prématurément ses soupçons", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Représailles évitées par la discrétion.", "groups": [{"position": 1, "keywords": ["représailles évitées", "soupçons discrets", "complices présents"]}]}]}]}'::jsonb);
SELECT fn_cp_import_case('vuln-personne-agee-isolee-negligence-familiale', '{"slug": "vuln-personne-agee-isolee-negligence-familiale", "title": "Le logement est insalubre, la famille dit passer chaque semaine", "theme_slug": "personnes-vulnerables", "difficulty": "difficile", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 30, "situation_text": "Il est 11 heures. Au domicile d''une personne âgée isolée, vous constatez un logement insalubre alors que la famille affirme y passer chaque semaine pour s''occuper de cette personne, ces versions contradictoires posant la question d''une négligence sans violence caractérisée qui reste néanmoins préjudiciable à cette personne âgée. Cette configuration, où cette maltraitance par omission se distingue des violences actives déjà rencontrées dans d''autres situations, nécessite de constater objectivement l''état de ce logement et de cette personne sans accuser prématurément cette famille sur la base de ces seules apparences.\n\nCette situation, caractéristique des négligences qui peuvent affecter une personne âgée isolée sans qu''aucune violence active ne soit exercée à son encontre, impose une constatation rigoureuse qui établisse objectivement les faits avant toute appréciation définitive sur les responsabilités de cette famille.\n\nCette configuration nécessite de constater objectivement l''état de ce logement sans accuser prématurément cette famille, cette exigence restant essentielle pour établir les faits de cette négligence tout en respectant les droits de chacun jusqu''à leur établissement définitif.", "questions": [{"position": 1, "max_points": 5, "label": "Comment constatez-vous objectivement l''état de ce logement insalubre et de cette personne âgée ?", "hint": "Cette constatation doit rester objective, cette rigueur restant essentielle pour établir factuellement cette situation avant toute appréciation définitive sur les responsabilités de cette famille.", "perfect": "Je décris précisément l''état de ce logement constaté, cette description objective restant essentielle pour cette procédure de constatation.\n\nJe reste factuelle sur l''état physique et psychologique de cette personne âgée, cette observation restant utile pour évaluer l''impact de cette situation sur sa santé.\n\nJe reste attentive à recueillir, si possible, le témoignage de cette personne âgée elle-même sur sa situation vécue au quotidien.\n\nJe reste attentive à documenter cette situation par des éléments matériels appropriés, cette traçabilité restant utile pour la suite de cette procédure.", "points": [{"position": 1, "label": "Décrire précisément l''état de ce logement constaté", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : description objective de la situation.", "groups": [{"position": 1, "keywords": ["logement décrit", "état constaté", "description objective"]}]}, {"position": 2, "label": "Observer factuellement l''état physique et psychologique de cette personne âgée", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Impact sur la santé évalué.", "groups": [{"position": 1, "keywords": ["état observé", "impact évalué", "santé considérée"]}]}, {"position": 3, "label": "Recueillir le témoignage de cette personne âgée sur sa situation vécue", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Témoignage direct de la personne concernée.", "groups": [{"position": 1, "keywords": ["témoignage recueilli", "situation vécue", "personne entendue"]}]}, {"position": 4, "label": "Documenter cette situation par des éléments matériels appropriés", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Traçabilité utile pour la procédure.", "groups": [{"position": 1, "keywords": ["situation documentée", "éléments matériels", "traçabilité assurée"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment évitez-vous d''accuser prématurément cette famille sur la base de ces seules apparences ?", "hint": "Cette réserve doit rester constante, cette exigence restant essentielle pour ne pas conclure prématurément sur les responsabilités de cette famille avant l''établissement complet des faits de cette situation.", "perfect": "Je reste attentive à ne pas conclure prématurément sur la responsabilité de cette famille avant l''établissement complet des faits de cette situation.\n\nJe reste factuelle en recueillant la version de cette famille sur la fréquence réelle de ses visites et sur les raisons de cet état constaté.\n\nJe reste attentive à envisager d''autres explications possibles à cette insalubrité, comme un refus d''aide de cette personne âgée elle-même.\n\nJe reste attentive à transmettre ce dossier aux autorités compétentes qui détermineront les responsabilités exactes de cette situation.", "points": [{"position": 1, "label": "Ne pas conclure prématurément sur la responsabilité de cette famille", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : réserve avant établissement complet des faits.", "groups": [{"position": 1, "keywords": ["responsabilité différée", "faits établis", "réserve appliquée"]}]}, {"position": 2, "label": "Recueillir la version de cette famille sur la fréquence de ses visites", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Version de la famille recueillie.", "groups": [{"position": 1, "keywords": ["version recueillie", "visites précisées", "famille entendue"]}]}, {"position": 3, "label": "Envisager d''autres explications possibles à cette insalubrité", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Explications alternatives envisagées.", "groups": [{"position": 1, "keywords": ["explications envisagées", "refus d''aide", "insalubrité expliquée"]}]}, {"position": 4, "label": "Transmettre ce dossier aux autorités compétentes pour déterminer les responsabilités", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Détermination des responsabilités par l''autorité compétente.", "groups": [{"position": 1, "keywords": ["dossier transmis", "autorités compétentes", "responsabilités déterminées"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment assurez-vous la protection immédiate de cette personne âgée en attendant ces conclusions ?", "hint": "Cette protection immédiate doit rester proportionnée, cette exigence restant essentielle pour préserver la santé de cette personne âgée sans attendre l''issue complète de cette procédure d''établissement des faits.", "perfect": "Je reste attentive à évaluer si cette insalubrité présente un risque immédiat pour la santé de cette personne âgée, cette évaluation restant prioritaire.\n\nJe reste factuelle sur les besoins urgents de cette personne, sollicitant si nécessaire une intervention sociale ou médicale rapide.\n\nJe reste attentive à signaler cette situation aux services sociaux compétents, cette transmission restant nécessaire pour cette protection immédiate.\n\nJe reste disponible pour un suivi de cette situation, cette disponibilité restant utile pour m''assurer de l''amélioration effective des conditions de vie de cette personne.", "points": [{"position": 1, "label": "Évaluer si cette insalubrité présente un risque immédiat pour la santé", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : évaluation prioritaire du risque immédiat.", "groups": [{"position": 1, "keywords": ["risque évalué", "santé prioritaire", "insalubrité mesurée"]}]}, {"position": 2, "label": "Solliciter une intervention sociale ou médicale rapide si nécessaire", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Besoins urgents pris en compte.", "groups": [{"position": 1, "keywords": ["intervention sollicitée", "besoins urgents", "aide rapide"]}]}, {"position": 3, "label": "Signaler cette situation aux services sociaux compétents", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Transmission nécessaire pour cette protection immédiate.", "groups": [{"position": 1, "keywords": ["services sociaux", "situation signalée", "protection assurée"]}]}, {"position": 4, "label": "Rester disponible pour un suivi de cette situation", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Amélioration effective des conditions vérifiée.", "groups": [{"position": 1, "keywords": ["suivi assuré", "conditions améliorées", "disponibilité maintenue"]}]}]}]}'::jsonb);
SELECT fn_cp_import_case('vuln-personne-en-detresse-refuse-hopital', '{"slug": "vuln-personne-en-detresse-refuse-hopital", "title": "Elle dit préférer rester dehors qu''être enfermée", "theme_slug": "personnes-vulnerables", "difficulty": "moyen", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 25, "situation_text": "Il est 21 heures. Sur la voie publique, une personne en détresse manifeste vous dit préférer rester dehors plutôt que d''être enfermée à l''hôpital, ce refus s''appuyant sur une expérience institutionnelle passée vécue négativement plutôt que sur un simple caprice ou une incapacité de discernement. Cette configuration, où ce refus reste fondé sur une méfiance compréhensible malgré le risque réel que cette situation continue de présenter, nécessite de comprendre précisément le motif de ce refus avant d''insister davantage sur cette hospitalisation qu''elle rejette.\n\nCette situation, caractéristique des refus de prise en charge qui peuvent être motivés par une expérience institutionnelle négative plutôt que par un simple déni de la réalité de sa propre situation, impose une écoute attentive de ces raisons avant toute action qui pourrait s''avérer contre-productive si elle ne tient pas compte de cette méfiance légitime.\n\nCette configuration nécessite de comprendre le motif de ce refus avant d''insister, cette exigence restant essentielle pour adapter votre réponse à cette méfiance institutionnelle plutôt que de la renforcer par une insistance mal comprise.", "questions": [{"position": 1, "max_points": 5, "label": "Comment comprenez-vous le motif de ce refus avant d''insister sur cette hospitalisation ?", "hint": "Cette compréhension doit rester préalable, cette exigence restant essentielle pour adapter votre réponse à cette méfiance institutionnelle plutôt que de la renforcer par une insistance mal comprise.", "perfect": "J''écoute attentivement les raisons de ce r